function validate([tasks]) {
  if (!Array.isArray(tasks) || tasks.length < 1 || tasks.length > 2000) return 'tasks needs 1 to 2000 entries.';
  for (const task of tasks) {
    if (!Array.isArray(task) || task.length !== 3 || !task.every(Number.isInteger)) return 'Each task is [start, end, duration] with integers.';
    const [start, end, duration] = task;
    if (start < 1 || start > 2000 || end < 1 || end > 2000) return 'start and end are between 1 and 2000.';
    if (duration < 1 || duration > end - start + 1) return 'duration is between 1 and end - start + 1.';
  }
  return null;
}

