function findMinimumTime(tasks) {
  tasks.sort((a, b) => a[1] - b[1]);
  const on = new Array(2001).fill(false);
  let total = 0;
  for (const [start, end, duration] of tasks) {
    let need = duration;
    for (let second = start; second <= end; second++) {
      if (on[second]) need--;
    }
    for (let second = end; need > 0; second--) {
      if (!on[second]) {
        on[second] = true;
        need--;
        total++;
      }
    }
  }
  return total;
}

