function findMinimumTime(tasks) {
  // Seconds between two consecutive window boundaries lie in exactly the same windows, so only how many
  // of them are on matters. Try every count for every such piece and keep the cheapest choice that works.
  const cuts = new Set();
  for (const [s, e] of tasks) { cuts.add(s); cuts.add(e + 1); }
  const points = [...cuts].sort((a, b) => a - b);
  const pieces = [];
  for (let i = 0; i + 1 < points.length; i++) {
    const a = points[i], b = points[i + 1] - 1;
    if (tasks.some(([s, e]) => s <= a && b <= e)) pieces.push([a, b]);
  }
  const counts = new Array(pieces.length).fill(0);
  let best = Infinity;
  const search = (i, used) => {
    if (used >= best) return;
    if (i === pieces.length) {
      const ok = tasks.every(([s, e, d]) => {
        let got = 0;
        pieces.forEach(([a, b], j) => { if (s <= a && b <= e) got += counts[j]; });
        return got >= d;
      });
      if (ok) best = used;
      return;
    }
    const [a, b] = pieces[i];
    for (let c = 0; c <= b - a + 1; c++) { counts[i] = c; search(i + 1, used + c); }
    counts[i] = 0;
  };
  search(0, 0);
  return best;
}

