function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  // Small windows stay within a short stretch of seconds so the brute force can try every on/off pattern.
  const base = large ? 1 : 1 + Math.floor(rand() * 1990);
  const span = large ? 2000 : 2 + Math.floor(rand() * 7);
  const longest = large ? [20, 200, 2000][Math.floor(rand() * 3)] : span;
  const tasks = [];
  for (let i = 0; i < n; i++) {
    const length = 1 + Math.floor(rand() * Math.min(longest, span));
    const start = base + Math.floor(rand() * (span - length + 1));
    const end = start + length - 1;
    const duration = 1 + Math.floor(rand() * (rand() < 0.5 ? length : Math.max(1, Math.floor(length / 4))));
    tasks.push([start, end, duration]);
  }
  return [tasks];
}
